// Generates docs/RULES.md and docs/rules/<CODE>.md from the rule catalogue, including live output for each example.
// Usage: node scripts/gen-docs.ts [--check]   (--check fails if the generated files differ from what is on disk)
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { allRules, formats, lintText, renderPretty } from '../src/index.ts';
import type { Example, RuleMeta } from '../src/index.ts';

const root = join(import.meta.dirname, '..');
const dir = join(root, 'docs', 'rules');
const check = process.argv.includes('--check');
const files = new Map<string, string>();

const visible = (text: string) => text.replace(/\t/g, '→').replace(/\r/g, '␍').replace(/ /g, '⍽').replace(/\x00/g, '␀').replace(/﻿/g, '');
const levelText = (r: RuleMeta) => {
  const strict = r.strict ?? r.level;
  return strict === r.level ? `\`${r.level}\`` : `\`${r.level}\` by default, \`${strict}\` with \`--strict\``;
};
const formatName = (id: string) => (id === 'text' ? 'Any format' : formats.find((f) => f.id === id)?.name ?? id);
const lintExample = (r: RuleMeta, e: Example) => {
  const fmt = r.format === 'text' ? e.format ?? 'fasta' : r.format;
  const res = lintText(e.text, { format: fmt, filename: `example.${fmt}`, profile: e.profile ?? (r.level === 'off' ? 'strict' : 'default'), select: [r.code], maxPerRule: 2, ...(e.options ? { formatOptions: { [fmt]: e.options } } : {}) });
  return renderPretty(res, { color: false }).split('\n').slice(0, -1).join('\n').trimEnd();
};

for (const r of allRules()) {
  const out: string[] = [];
  out.push(`# ${r.code}: ${r.title}`, '');
  out.push('| | |', '|---|---|', `| Name | \`${r.name}\` |`, `| Format | ${formatName(r.format)} |`, `| Level | ${levelText(r)} |`);
  if (r.spec) out.push(`| Source | ${r.spec} |`);
  if (r.fixable) out.push('| Fixable | yes, with `biolint --fix` |');
  out.push('', r.explanation, '');
  const bad = r.examples?.bad ?? [];
  const good = r.examples?.good ?? [];
  if (bad.length) {
    out.push('## Example', '');
    for (const e of bad) {
      if (e.note) out.push(`${e.note[0]!.toUpperCase()}${e.note.slice(1)}:`, '');
      if (e.options) out.push(`With ${Object.entries(e.options).map(([k, v]) => `\`-o ${r.format}.${k}=${v}\``).join(' ')}:`, '');
      out.push('```text', visible(e.text).trimEnd(), '```', '', 'biolint reports:', '', '```text', lintExample(r, e), '```', '');
    }
    out.push('In these listings `→` stands for a tab.', '');
  }
  if (good.length) {
    out.push('## Accepted', '');
    for (const e of good) out.push('```text', visible(e.text).trimEnd(), '```', '');
  }
  out.push('## Configuration', '', `Silence it with \`--ignore ${r.code}\`, or check only this rule with \`--select ${r.code}\`.`, '');
  files.set(join(dir, `${r.code}.md`), out.join('\n'));
}

// Index
const idx: string[] = ['# Rules', '', '<!-- Generated by `npm run docs`. Do not edit by hand. -->', '',
  `biolint has ${allRules().length} rules. Each one has a stable code, a default level, and a page with an example.`, '',
  '`--strict` raises the rules marked below to the level in the last column. `--explain CODE` prints a rule in the terminal.', ''];
const groups = ['text', ...formats.map((f) => f.id)];
for (const g of groups) {
  const rs = allRules().filter((r) => r.format === g);
  if (!rs.length) continue;
  idx.push(`## ${formatName(g)}`, '', '| Code | Name | Default | Strict | What it finds |', '|---|---|---|---|---|');
  for (const r of rs) idx.push(`| [${r.code}](rules/${r.code}.md) | \`${r.name}\` | ${r.level} | ${r.strict ?? r.level} | ${r.title}${r.fixable ? ' (fixable)' : ''} |`);
  idx.push('');
}
files.set(join(root, 'docs', 'RULES.md'), idx.join('\n'));

if (check) {
  const stale = [...files].filter(([p, c]) => !existsSync(p) || readFileSync(p, 'utf8') !== c).map(([p]) => p.slice(root.length + 1));
  const extra = existsSync(dir) ? readdirSync(dir).filter((f) => !files.has(join(dir, f))) : [];
  if (stale.length || extra.length) { console.error(`generated docs are out of date (run \`npm run docs\`):\n  ${[...stale, ...extra.map((f) => 'docs/rules/' + f + ' (stale)')].join('\n  ')}`); process.exit(1); }
  console.log(`docs are up to date (${files.size} files)`);
} else {
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
  for (const [p, c] of files) writeFileSync(p, c);
  console.log(`wrote ${files.size} files`);
}
